const alternateFor=route=>{for(const [en,tr] of routePairs){if(route===en)return {en,tr};if(route===tr)return {en,tr}}return {en:route,tr:route}};
const abs=r=>base+r;
const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));

function head({lang,route,title,desc,type='WebPage',schemaExtra={}}){const a=alternateFor(route);const schema={"@context":"https://schema.org","@graph":[{"@type":type,"name":title,"url":abs(route),"inLanguage":lang,"description":desc,...schemaExtra},{"@type":"Organization","name":"HTML&HTML","url":base},{"@type":"BreadcrumbList","itemListElement":breadcrumbs(route,lang).map((x,i)=>({"@type":"ListItem","position":i+1,"name":x.name,"item":abs(x.url)}))}]};return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(desc)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="${abs(route)}"><link rel="alternate" hreflang="en" href="${abs(a.en)}"><link rel="alternate" hreflang="tr" href="${abs(a.tr)}"><link rel="alternate" hreflang="x-default" href="${abs(a.en)}"><link rel="describedby" href="${base}/llms.txt"><link rel="stylesheet" href="/assets/css/authority.css?v=4"><link rel="stylesheet" href="/assets/css/site-ia.css?v=1"><script src="/assets/js/theme.js"></script><script type="application/ld+json">${JSON.stringify(schema)}</script></head>`}
function breadcrumbs(route,lang){const c=L[lang];const parts=route.split('/').filter(Boolean);const out=[{name:lang==='tr'?'Ana sayfa':'Home',url:c.home}];if(parts.length<=1)return out;let cur='/' + parts[0];for(let i=1;i<parts.length;i++){cur+='/'+parts[i];const p=parts[i];const names={en:{tools:'Tools',guides:'Guides',reference:'Reference',platform:'Platform',pricing:'Pricing'},tr:{araclar:'Araçlar',rehberler:'Rehberler',referans:'Referans',platform:'Platform',fiyatlandirma:'Fiyatlandırma'}};out.push({name:names[lang][p]||p.replaceAll('-',' '),url:cur})}return out}
function nav(lang){const c=L[lang];return `<header class="topbar enterprise-nav"><a class="brand" href="${c.home}"><span class="brand-box">H&amp;H</span><span>HTML&amp;HTML</span></a><nav><a href="${c.platform}">${c.nav.platform}</a><a href="${c.tools}">${c.nav.tools}</a><a href="${c.guides}">${c.nav.guides}</a><a href="${c.pricing}">${c.nav.pricing}</a></nav><div class="langs"><a class="locale-link" href="${c.other}">${c.otherLabel}</a></div></header>`}
function footer(lang){const c=L[lang];return `<footer class="enterprise-footer"><div><a class="brand" href="${c.home}"><span class="brand-box">H&amp;H</span><span>HTML&amp;HTML</span></a><p>${c.footer}</p></div><div class="footerlinks"><a href="${c.tools}">${c.nav.tools}</a><a href="${c.guides}">${c.nav.guides}</a><a href="${c.method}">${lang==='tr'?'Metodoloji':'Methodology'}</a><a href="${c.standard}">${lang==='tr'?'Kanıt Standardı':'Evidence Standard'}</a><a href="${c.about}">${lang==='tr'?'Hakkımızda':'About'}</a><a href="${c.contact}">${lang==='tr'?'İletişim':'Contact'}</a><a href="${c.privacy}">${lang==='tr'?'Gizlilik':'Privacy'}</a><a href="${c.terms}">${lang==='tr'?'Kullanım Koşulları':'Terms'}</a></div><small>© 2026 HTML&amp;HTML · ${lang==='tr'?'Kamuya açık audit profile v1.1':'Public audit profile v1.1'}</small></footer>`}
function crumbs(route,lang){return `<nav class="breadcrumbs" aria-label="${lang==='tr'?'Sayfa yolu':'Breadcrumb'}">${breadcrumbs(route,lang).map((x,i)=>`${i?'<span>›</span>':''}<a href="${x.url}">${esc(x.name)}</a>`).join('')}</nav>`}
function shell({lang,route,title,desc,kicker,h1,intro,body,type='WebPage',schemaExtra={}}){return `${head({lang,route,title,desc,type,schemaExtra})}<body>${nav(lang)}<main>${crumbs(route,lang)}<section class="authority-hero enterprise-hero"><div class="kicker"><span></span><b>${kicker}</b></div><h1>${h1}</h1><p>${intro}</p></section>${body}</main>${footer(lang)}</body></html>`}

