function toolPage(lang,t){const c=L[lang];const route=t.slug;const title=`${t.name} — HTML&HTML`;const desc=t.desc;const checks=t.checks.map((x,i)=>`<article class="authority-card"><b>0${i+1}</b><h3>${esc(x)}</h3><p>${lang==='tr'?'Bu kontrol aynı 12-motor tarama çekirdeğinden gelen, dışarıdan ölçülebilir kanıtlarla raporlanır.':'This check is reported from the same 12-engine scan core using externally measurable evidence.'}</p></article>`).join('');return shell({lang,route,title,desc,kicker:lang==='tr'?'ODAKLI ÜCRETSİZ ARAÇ / TEK CANONICAL MOTOR':'FOCUSED FREE TOOL / ONE CANONICAL ENGINE',h1:t.h1,intro:t.intro,type:'SoftwareApplication',schemaExtra:{applicationCategory:'DeveloperApplication',operatingSystem:'Web',offers:{'@type':'Offer',price:'0',priceCurrency:'USD'}},body:`<section class="tool-shell" id="scanner"><div class="tool-panel"><h2>${lang==='tr'?'Alan adını girin':'Enter a domain'}</h2><p>${lang==='tr'?'Protokol veya www yazmanız gerekmez. Sonuçta yalnızca bu sayfanın odaklandığı motorlar gösterilir; arka planda canonical scan sözleşmesi korunur.':'Protocol and www are optional. The result view shows only this page’s focused engines while the canonical scan contract remains unchanged.'}</p><form class="tool-form" id="toolScanForm"><input id="toolDomain" aria-label="${lang==='tr'?'Alan adı':'Domain'}" autocomplete="url" placeholder="${c.domain}" required><button type="submit">${c.checking}</button></form><small class="tool-note">${lang==='tr'?'Kayıt yok · Public HTTP/HTTPS yüzeyi · SSRF fail-closed · En fazla 50 public HTML sayfası':'No signup · Public HTTP/HTTPS surface · SSRF fail-closed · Up to 50 public HTML pages'}</small><div id="toolStatus" class="tool-status" hidden></div><div id="toolResult" class="tool-result" hidden><div class="tool-score" id="toolScore"></div><div><p id="toolMeta" class="tool-note"></p><div id="toolFindings" class="tool-findings"></div></div></div></div></section><section class="section"><header><span class="eyebrow">${lang==='tr'?'KAPSAM':'SCOPE'}</span><h2>${lang==='tr'?'Bu araç neyi ölçer?':'What does this tool measure?'}</h2><p>${lang==='tr'?'Sayfa tek bir arama niyetine odaklanır. Puanlama mantığı veya ölçüm motoru kopyalanmaz.':'The page targets one search intent. Scoring logic and measurement code are not duplicated.'}</p></header><div class="authority-grid">${checks}</div></section><section class="section"><div class="authority-callout"><div><h3>${lang==='tr'?'Sorunu gördünüz. Uygulama sırası ayrı üründür.':'You found the issue. Implementation order is a separate product.'}</h3><p>${lang==='tr'?'Ücretsiz sonuç bulgu, URL, severity, confidence, source class ve evidence gösterir. Fix Mandate yalnız uygulama sözleşmesini, testleri ve rollback’i açar.':'The free result shows finding, URL, severity, confidence, source class and evidence. The Fix Mandate unlocks only implementation sequence, tests and rollback.'}</p></div><a href="${c.fix}">${lang==='tr'?'Fix Mandate’i incele':'See the Fix Mandate'}</a></div><div class="related-links"><a href="${c.tools}">← ${lang==='tr'?'Tüm araçlar':'All tools'}</a><a href="${t.guide}">${lang==='tr'?'İlgili rehberi oku':'Read the related guide'} →</a></div></section><script>document.body.dataset.toolCategories='${t.cats}'</script><script src="/assets/js/authority-tool.js" defer></script>`})}

function toolsHub(lang){const c=L[lang];const items=tools[lang].map(t=>`<article class="ia-card"><span>${t.existing?(lang==='tr'?'CANLI ARAÇ':'LIVE TOOL'):(lang==='tr'?'ODAKLI ARAÇ':'FOCUSED TOOL')}</span><h3>${esc(t.name)}</h3><p>${esc(t.desc)}</p><a href="${t.slug}">${lang==='tr'?'Aracı aç':'Open tool'} →</a></article>`).join('');return shell({lang,route:c.tools,title:lang==='tr'?'AI ve Teknik Web Sitesi Araçları — HTML&HTML':'AI & Technical Website Tools — HTML&HTML',desc:lang==='tr'?'Tek canonical 12-motor tarama çekirdeğinden beslenen odaklı AI, SEO, schema, güvenlik, erişilebilirlik ve link kontrol araçları.':'Focused AI, SEO, schema, security, accessibility and link tools powered by one canonical 12-engine scan core.',kicker:lang==='tr'?'ARAÇ DİZİNİ / TEK MOTOR':'TOOL DIRECTORY / ONE ENGINE',h1:lang==='tr'?'Her soru için <em>ayrı niyet sayfası.</em> Her ölçüm için tek çekirdek.':'One <em>intent page</em> per question. One core for every measurement.',intro:lang==='tr'?'Araç sayfaları SEO ve LLM retrieval için konuyu ayırır; teknik karar modeli ise ayrışmaz. Böylece içerik mimarisi büyürken metodoloji drift etmez.':'Tool pages separate search and retrieval intent while the technical decision model stays unified. The information architecture can grow without methodology drift.',body:`<section class="section compact-section"><div class="ia-grid">${items}</div></section><section class="section"><div class="authority-callout"><div><h3>${lang==='tr'?'Nereden başlayacağınızı bilmiyor musunuz?':'Not sure where to start?'}</h3><p>${lang==='tr'?'Tam 12-motor tarama, tek bir başlangıç baseline’ı üretir.':'The full 12-engine scan gives you one technical baseline.'}</p></div><a href="${lang==='tr'?'/tr/site-tarama':'/en/website-scanner'}">${c.scan}</a></div></section>`})}

function homePage(lang){const c=L[lang];const cards=tools[lang].slice(0,6).map(t=>`<article class="ia-card"><span>${lang==='tr'?'ARAÇ':'TOOL'}</span><h3>${esc(t.name)}</h3><p>${esc(t.desc)}</p><a href="${t.slug}">${lang==='tr'?'Aç':'Open'} →</a></article>`).join('');return `${head({lang,route:c.home,title:c.homeTitle,desc:c.homeDesc,type:'WebSite',schemaExtra:{publisher:{'@type':'Organization',name:'HTML&HTML'}}})}<body>${nav(lang)}<main><section class="hub-hero"><div class="kicker"><span></span><b>${c.heroKicker}</b></div><h1>${c.heroTitle}</h1><p>${c.heroCopy}</p><div class="authority-proof">${c.proof.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="hub-scan"><form class="tool-form" id="toolScanForm"><input id="toolDomain" aria-label="${lang==='tr'?'Alan adı':'Domain'}" autocomplete="url" placeholder="${c.domain}" required><button type="submit">${c.scan}</button></form><div id="toolStatus" class="tool-status" hidden></div><div id="toolResult" class="tool-result" hidden><div class="tool-score" id="toolScore"></div><div><p id="toolMeta" class="tool-note"></p><div id="toolFindings" class="tool-findings"></div></div></div></div></section><section class="section hub-section"><header><span class="eyebrow">01 / ${lang==='tr'?'ARAÇLAR':'TOOLS'}</span><h2>${c.sectionTools}</h2><p>${c.sectionToolsCopy}</p></header><div class="ia-grid">${cards}</div><div class="section-link"><a href="${c.tools}">${lang==='tr'?'10 aracın tamamını gör':'See all 10 tools'} →</a></div></section><section class="section hub-section"><header><span class="eyebrow">02 / ${lang==='tr'?'ÇALIŞMA AKIŞI':'WORKFLOW'}</span><h2>${c.sectionFlow}</h2><p>${c.sectionFlowCopy}</p></header><div class="flow-grid"><article><b>01</b><h3>${lang==='tr'?'Tara':'Scan'}</h3><p>${lang==='tr'?'Public yüzeyi ölç, unknown sinyali uydurma.':'Measure the public surface and leave unknown signals unknown.'}</p></article><article><b>02</b><h3>${lang==='tr'?'Kanıtla':'Evidence'}</h3><p>${lang==='tr'?'Bulguya URL, confidence ve source class bağla.':'Attach URL, confidence and source class to every valid finding.'}</p></article><article><b>03</b><h3>${lang==='tr'?'Düzelt':'Fix'}</h3><p>${lang==='tr'?'Fix Mandate ile root fix, test ve rollback sözleşmesi üret.':'Use the Fix Mandate for root fix, tests and rollback.'}</p></article><article><b>04</b><h3>${lang==='tr'?'Yeniden ölç':'Re-scan'}</h3><p>${lang==='tr'?'Aynı karar sözleşmesiyle before/after doğrula.':'Verify before/after with the same decision contract.'}</p></article></div><div class="dual-cta"><a class="solid-cta" href="${c.platform}">${lang==='tr'?'Platformu incele':'Explore the platform'}</a><a href="${c.fix}">${lang==='tr'?'Fix Mandate':'Fix Mandate'} →</a></div></section><section class="section hub-section"><header><span class="eyebrow">03 / ${lang==='tr'?'YÖNETİŞİM':'GOVERNANCE'}</span><h2>${c.sourceTitle}</h2><p>${c.sourceCopy}</p></header><div class="ia-grid ia-grid-3"><article class="ia-card"><span>PROFILE</span><h3>${lang==='tr'?'Kanıt Standardı':'Evidence Standard'}</h3><p>${lang==='tr'?'12 motorun açık ürün profilini, sınırlarını ve invariants kurallarını görün.':'Inspect the public product profile, scan boundaries and invariants behind all 12 engines.'}</p><a href="${c.standard}">${lang==='tr'?'Standardı aç':'Open standard'} →</a></article><article class="ia-card"><span>METHOD</span><h3>${lang==='tr'?'Metodoloji':'Methodology'}</h3><p>${lang==='tr'?'Unknown, confidence, scoring ve kaynak sınıflarının nasıl işlendiğini görün.':'See how unknown states, confidence, scoring and source classes are handled.'}</p><a href="${c.method}">${lang==='tr'?'Metodolojiyi aç':'Open methodology'} →</a></article><article class="ia-card"><span>REFERENCE</span><h3>${lang==='tr'?'AI Tarayıcı Referansı':'AI Crawler Reference'}</h3><p>${lang==='tr'?'Arama, kullanıcı yönlendirmeli retrieval ve model-geliştirme botlarını birbirine karıştırmadan inceleyin.':'Separate search, user-directed retrieval and model-development controls without conflating them.'}</p><a href="${c.crawlerRef}">${lang==='tr'?'Referansı aç':'Open reference'} →</a></article></div></section></main>${footer(lang)}<script>document.body.dataset.toolCategories='crawl,technical,ai,llms,schema,performance,accessibility,security,trust,agent,conversion,links'</script><script src="/assets/js/authority-tool.js" defer></script></body></html>`}

function platformPage(lang){const c=L[lang];return shell({lang,route:c.platform,title:lang==='tr'?'AI Web Sitesi Hazırlık Platformu — HTML&HTML':'AI Website Readiness Platform — HTML&HTML',desc:lang==='tr'?'HTML&HTML platform mimarisi: 12-motor public scan, kanıt zinciri, Fix Mandate, re-scan ve AI mention ölçümü.':'HTML&HTML platform architecture: 12-engine public scan, evidence chain, Fix Mandate, re-scan and AI mention measurement.',kicker:lang==='tr'?'PLATFORM / TARAYICI DEĞİL KARAR SİSTEMİ':'PLATFORM / NOT JUST A CHECKER',h1:lang==='tr'?'Tek bir validator değil. <em>Ölçümden uygulama kanıtına sistem.</em>':'Not another validator. <em>A system from measurement to implementation proof.</em>',intro:lang==='tr'?'HTML&HTML’nin savunulabilir değeri tek bir dosya veya bot kontrolünden değil, aynı karar sözleşmesini scan → evidence → fix → re-scan zincirinde korumasından gelir.':'HTML&HTML is defensible because the same decision contract survives the full scan → evidence → fix → re-scan lifecycle, not because it checks one file or one bot.',body:`<section class="section"><header><span class="eyebrow">01 / ARCHITECTURE</span><h2>${lang==='tr'?'Beş katman. Bir karar sözleşmesi.':'Five layers. One decision contract.'}</h2></header><div class="flow-grid"><article><b>01</b><h3>Scan</h3><p>${lang==='tr'?'12 motor, bounded crawl, SSRF fail-closed.':'12 engines, bounded crawl, SSRF fail-closed.'}</p></article><article><b>02</b><h3>Evidence</h3><p>${lang==='tr'?'Severity, confidence, source class, URL, evidence.':'Severity, confidence, source class, URL and evidence.'}</p></article><article><b>03</b><h3>Fix</h3><p>${lang==='tr'?'Root fix, recovery, prevention, acceptance, rollback.':'Root fix, recovery, prevention, acceptance and rollback.'}</p></article><article><b>04</b><h3>Re-scan</h3><p>${lang==='tr'?'Aynı domain, aynı motor, before/after.':'Same domain, same engine, before/after.'}</p></article><article><b>05</b><h3>Monitor</h3><p>${lang==='tr'?'Mention ve readiness değişimini zaman içinde izlemeye uygun temel.':'A foundation for monitoring mention and readiness change over time.'}</p></article></div></section><section class="section"><header><span class="eyebrow">02 / BOUNDARIES</span><h2>${lang==='tr'?'Sınırlar ürünün parçasıdır.':'Boundaries are part of the product.'}</h2><p>${lang==='tr'?'Public scan source dosya adı uydurmaz, Core Web Vitals üretmez, private ağı taramaz ve ranking/citation garantisi vermez.':'The public scan does not invent source paths, fabricate Core Web Vitals, crawl private networks or promise rankings/citations.'}</p></header><div class="authority-grid"><article class="authority-card"><b>PUBLIC</b><h3>${lang==='tr'?'Kanıt ücretsiz':'Evidence stays free'}</h3><p>${lang==='tr'?'Sorun, URL ve kanıt paywall arkasına saklanmaz.':'Issue, URL and evidence are not hidden behind a paywall.'}</p></article><article class="authority-card"><b>PAID</b><h3>${lang==='tr'?'Uygulama kesinliği':'Implementation precision'}</h3><p>${lang==='tr'?'Ücretli katman yalnız uygulama sırası, test ve rollback sözleşmesini satar.':'The paid layer sells implementation sequence, tests and rollback.'}</p></article><article class="authority-card"><b>UNKNOWN</b><h3>${lang==='tr'?'Bilinmeyen bilinmeyen kalır':'Unknown stays unknown'}</h3><p>${lang==='tr'?'Ölçülemeyen sinyal pass/fail gibi davranmaz.':'Unavailable evidence is not forced into pass or fail.'}</p></article></div></section><section class="section"><div class="authority-callout"><div><h3>${lang==='tr'?'Platformu gerçek domain üzerinde çalıştırın.':'Run the platform on a real domain.'}</h3><p>${lang==='tr'?'Tam tarama ücretsizdir; uygulama sözleşmesi ayrı üründür.':'The full scan is free; the implementation contract is a separate product.'}</p></div><a href="${lang==='tr'?'/tr/site-tarama':'/en/website-scanner'}">${c.scan}</a></div></section>`})}

function fixPage(lang){const c=L[lang];return shell({lang,route:c.fix,title:lang==='tr'?'Full Site Fix Mandate — Uygulama Sözleşmesi | HTML&HTML':'Full Site Fix Mandate — Implementation Contract | HTML&HTML',desc:lang==='tr'?'Bir domain için doğrulanmış scan bulgularını P0–P3 uygulama sırası, root fix, recovery, prevention, acceptance/regression test ve rollback sözleşmesine dönüştüren $149 ürün.':'A $149 implementation-grade contract that converts verified scan findings for one domain into P0–P3 order, root fix, recovery, prevention, acceptance/regression tests and rollback.',kicker:'FULL SITE FIX MANDATE / $149',h1:lang==='tr'?'Rapor değil. <em>Uygulanabilir düzeltme sözleşmesi.</em>':'Not a report. <em>An executable fix contract.</em>',intro:lang==='tr'?'Ücretsiz scan neyin yanlış olduğunu ve kanıtını gösterir. Fix Mandate, yalnızca kanıtlanmış bulgular için hangi sırada ne değişeceğini ve değişikliğin nasıl doğrulanacağını tanımlar.':'The free scan shows what is wrong and what proves it. The Fix Mandate defines what should change, in what order, and how the change is verified — only for validated findings.',body:`<section class="section"><header><span class="eyebrow">DELIVERABLE</span><h2>${lang==='tr'?'Her bulgu uygulama kontratına dönüşür.':'Every valid finding becomes an implementation contract.'}</h2></header><div class="method-list"><div class="method-item"><b>P0–P3</b><div><h3>${lang==='tr'?'Uygulama sırası':'Implementation order'}</h3><p>${lang==='tr'?'Risk, bağımlılık ve regression etkisine göre sıralanır.':'Ordered by risk, dependency and regression impact.'}</p></div></div><div class="method-item"><b>ROOT FIX</b><div><h3>${lang==='tr'?'Kök neden':'Root cause'}</h3><p>${lang==='tr'?'Semptomu gizlemek yerine doğrulanmış neden sınıfı hedeflenir.':'Targets the validated cause class rather than hiding the symptom.'}</p></div></div><div class="method-item"><b>TEST</b><div><h3>${lang==='tr'?'Acceptance + regression':'Acceptance + regression'}</h3><p>${lang==='tr'?'Düzeltmenin başarı koşulu ve bozabileceği komşu davranış tanımlanır.':'Defines success conditions and adjacent behavior that could regress.'}</p></div></div><div class="method-item"><b>ROLLBACK</b><div><h3>${lang==='tr'?'Geri dönüş':'Rollback'}</h3><p>${lang==='tr'?'Hangi durumda durulacağı ve geri alınacağı yazılır.':'Defines stop conditions and the reversal path.'}</p></div></div></div></section><section class="section"><header><span class="eyebrow">COMMERCIAL BOUNDARY</span><h2>${lang==='tr'?'Kanıtı satmıyoruz. Uygulama kesinliğini satıyoruz.':'We do not sell the evidence. We sell implementation precision.'}</h2></header><div class="pricing-grid pricing-two"><article><div class="pricehead"><span>${lang==='tr'?'ÜCRETSİZ TEŞHİS':'FREE DIAGNOSIS'}</span><strong>$0</strong></div><p>${lang==='tr'?'Bulgu, URL, severity, confidence, source class ve evidence.':'Finding, URL, severity, confidence, source class and evidence.'}</p><ul><li>12 ${lang==='tr'?'motor':'engines'}</li><li>${lang==='tr'?'En fazla 50 public HTML sayfası':'Up to 50 public HTML pages'}</li><li>${lang==='tr'?'Kanıt gizlenmez':'Evidence is not hidden'}</li></ul><a href="${lang==='tr'?'/tr/site-tarama':'/en/website-scanner'}">${c.scan}</a></article><article class="featured"><div class="pricehead"><span>FULL SITE FIX MANDATE</span><strong>$149</strong></div><p>${lang==='tr'?'1 domain / tek çalışma. 30 gün içinde 1 re-scan dahil.':'1 domain / one engagement. Includes 1 re-scan within 30 days.'}</p><ul><li>P0–P3</li><li>ROOT FIX → RECOVERY → PREVENTION</li><li>Acceptance + regression</li><li>Rollback + stop conditions</li></ul><a class="solid" href="/checkout">${lang==='tr'?'Ödeme durumu / checkout':'Checkout status'}</a></article></div></section>`})}

function pricingPage(lang){const c=L[lang];return shell({lang,route:c.pricing,title:lang==='tr'?'Fiyatlandırma — Ücretsiz Scan ve $149 Fix Mandate | HTML&HTML':'Pricing — Free Scan & $149 Fix Mandate | HTML&HTML',desc:lang==='tr'?'HTML&HTML fiyat sınırı: public 12-motor teşhis ücretsiz, Full Site Fix Mandate bir domain için $149. AI Mention Tracker erişim kontrollü ücretli modüldür.':'HTML&HTML commercial boundary: the public 12-engine diagnosis is free, the Full Site Fix Mandate is $149 per domain, and AI Mention Tracker is an access-gated paid module.',kicker:lang==='tr'?'FİYATLANDIRMA / KANIT ÜCRETSİZ':'PRICING / EVIDENCE STAYS FREE',h1:lang==='tr'?'Basit fiyat. <em>Net ürün sınırı.</em>':'Simple pricing. <em>A clear product boundary.</em>',intro:lang==='tr'?'Teşhis verisini saklayarak dönüşüm yaratmıyoruz. Ücretli ürün, doğrulanmış sorunu güvenli biçimde uygulamaya dönüştüren sözleşmedir.':'Conversion does not depend on hiding diagnostic evidence. The paid product is the contract that converts validated problems into safe implementation work.',body:`<section class="section"><div class="pricing-grid pricing-two"><article><div class="pricehead"><span>${lang==='tr'?'12-MOTOR TEŞHİS':'12-ENGINE DIAGNOSIS'}</span><strong>$0</strong></div><p>${lang==='tr'?'Kayıt olmadan public site surface taraması.':'Public website-surface diagnosis without signup.'}</p><ul><li>${lang==='tr'?'Tüm geçerli bulgular':'All valid findings'}</li><li>${lang==='tr'?'Severity + confidence + source class':'Severity + confidence + source class'}</li><li>${lang==='tr'?'URL + evidence':'URL + evidence'}</li><li>${lang==='tr'?'En fazla 50 public HTML sayfası':'Up to 50 public HTML pages'}</li></ul><a href="${lang==='tr'?'/tr/site-tarama':'/en/website-scanner'}">${c.scan}</a></article><article class="featured"><div class="pricehead"><span>FULL SITE FIX MANDATE</span><strong>$149</strong></div><p>${lang==='tr'?'Bir domain için implementation-grade sözleşme.':'Implementation-grade contract for one domain.'}</p><ul><li>P0–P3</li><li>ROOT FIX / RECOVERY / PREVENTION</li><li>Acceptance / regression</li><li>Rollback / stop conditions</li><li>30-day re-scan</li></ul><a class="solid" href="${c.fix}">${lang==='tr'?'Ürünü incele':'View product'}</a></article></div></section><section class="section"><header><span class="eyebrow">AI MENTION TRACKER</span><h2>${lang==='tr'?'Ayrı, erişim kontrollü ücretli modül.':'Separate access-gated paid module.'}</h2><p>${lang==='tr'?'Provider maliyetleri ve entitlement yapılandırması ürün sınırının parçasıdır. Sağlayıcı anahtarı yoksa sistem sonuç uydurmaz ve “not configured” döner.':'Provider cost and entitlement are part of the product boundary. If provider credentials are not configured, the system does not fabricate results and returns a not-configured state.'}</p></header><a class="text-cta" href="${lang==='tr'?'/tr/ai-mention-tracker':'/en/ai-mention-tracker'}">${lang==='tr'?'AI görünürlük modülünü incele':'Explore AI Mention Tracker'} →</a></section>`})}

const guideData={
 en:[
 {slug:'/en/guides/ai-website-readiness-checklist',tr:'/tr/rehberler/ai-web-sitesi-hazirlik-kontrol-listesi',title:'AI Website Readiness Checklist: A Technical Evidence-First Framework',desc:'A practical checklist for crawl access, technical SEO, AI crawler policy, llms.txt, structured data, accessibility, security, trust and links without treating any one signal as a ranking guarantee.',tool:'/en/website-scanner',sections:[['Start with crawlability, not AI labels','If a page cannot be fetched, indexed or discovered reliably, adding AI-specific files does not repair the underlying access path. Validate HTTP status, redirects, robots behavior, sitemap visibility and page discovery first. Keep search retrieval, training controls and user-directed retrieval conceptually separate.'],['Separate technical evidence from product heuristics','A useful readiness audit distinguishes direct HTTP/HTML evidence from vendor documentation, emerging proposals and internal heuristics. This prevents a score from implying more authority than the underlying rule actually has.'],['Treat machine-readable surfaces as layers','llms.txt, Markdown alternates, structured data and OpenAPI can improve machine readability or discovery context, but they do not replace crawlability, content quality or trustworthy site identity. Each layer should be measured independently.'],['Do not fabricate field performance data','Static HTML can reveal performance hygiene signals such as response size or script density, but reliable LCP, INP and CLS require field or lab data. An evidence-first audit should return NOT_MEASURED when the required data source is unavailable.'],['Close the loop with re-scan','Readiness work is complete only when the same decision contract is run again after implementation. Before/after evidence is more defensible than a one-time checklist because it shows which measurable conditions actually changed.']],sources:['https://www.rfc-editor.org/rfc/rfc9309.html','https://help.openai.com/en/articles/12627856-publishers-and-developers-faq','https://llmstxt.org/','https://www.w3.org/TR/WCAG22/']},
 {slug:'/en/guides/llms-txt',tr:'/tr/rehberler/llms-txt',title:'llms.txt: What It Is, What It Is Not, and How to Validate It',desc:'A sourced guide to llms.txt v2, discovery relationships, link reachability and the limits of the proposal.',tool:'/en/llms-txt-validator',sections:[['llms.txt is a proposal, not a mandatory ranking standard','The file is useful as an emerging convention for presenting a concise, LLM-oriented map of a site. It should not be described as an IETF, W3C or search-ranking requirement. That distinction belongs in both product messaging and scoring.'],['Structure is only the first check','A text file can be syntactically clean while pointing to broken or redirected resources. Validation should therefore separate Markdown structure from real HTTP reachability and report each failure with its own evidence.'],['Discovery matters','The current proposal includes discovery mechanisms such as rel="describedby" and Markdown alternate relationships. These are useful signals for machine discovery, but they remain proposal-level behavior and should not be scored like normative web protocol requirements.'],['Keep linked resources purposeful','An llms.txt file is more useful when it points to stable, canonical, high-information pages rather than a long list of thin URLs. A strong site information architecture makes the file easier to maintain and easier for retrieval systems to navigate.'],['Validate after deployment','Changes to routing, redirects or content types can silently break linked resources. Re-run the validator after deployment and treat the file as part of the site’s maintained machine-readable surface.']],sources:['https://llmstxt.org/','https://llmstxt.org/changes.html']},
 {slug:'/en/guides/ai-crawler-access',tr:'/tr/rehberler/ai-tarayici-erisimi',title:'AI Crawler Access: Robots.txt, Search Retrieval and Vendor-Specific Controls',desc:'A vendor-sourced guide to separating search crawlers, user-directed retrieval and model-development collection controls.',tool:'/en/ai-crawler-checker',sections:[['Robots rules are protocol behavior, vendor meaning is separate','RFC 9309 defines the Robots Exclusion Protocol. Vendor documentation defines what each crawler token is used for. A correct audit needs both layers because a syntactically valid robots rule does not explain the product purpose of a bot.'],['OpenAI search access is not a placement guarantee','OpenAI documents OAI-SearchBot for search eligibility. Allowing access can be a prerequisite for inclusion, but it does not guarantee placement, ranking or citation. GPTBot and search access should not be treated as the same control.'],['Anthropic exposes distinct crawler roles','Anthropic documents separate crawler identities for model-development collection, user-directed retrieval and search. Treating them as one generic “Claude bot” loses policy precision and can cause unintended blocking.'],['Perplexity and Google require their own reading','Perplexity documents robots behavior for PerplexityBot. Google documents common crawlers and Google-Extended separately. A single “allow AI” switch is therefore not a reliable governance model.'],['Test the live robots response','Do not audit a robots file from a CMS editor alone. Fetch the deployed robots.txt, follow redirects, resolve the effective user-agent groups and verify that the public site returns the policy you intended.']],sources:['https://www.rfc-editor.org/rfc/rfc9309.html','https://help.openai.com/en/articles/12627856-publishers-and-developers-faq','https://support.anthropic.com/en/articles/8896518-does-anthropic-crawl-data-from-the-web-and-how-can-site-owners-block-the-crawler','https://www.perplexity.ai/help-center/en/articles/10354969-how-does-perplexity-follow-robots-txt','https://developers.google.com/crawling/docs/crawlers-fetchers/google-common-crawlers']},
 {slug:'/en/guides/structured-data-for-ai',tr:'/tr/rehberler/ai-icin-yapisal-veri',title:'Structured Data for AI Readiness: What You Can Validate Reliably',desc:'How to use structured data as a measurable semantic layer without turning it into an AI citation promise.',tool:'/en/schema-validator',sections:[['Start with parseability','Broken JSON-LD is not a semantic asset. Validate that blocks parse correctly before debating entity strategy. A scanner can reliably report syntax and parse failures from public HTML.'],['Inventory entity types','A site may publish multiple entity types across templates. An inventory helps reveal inconsistent identity, missing product or organization context and template drift. The audit should describe what is present rather than inventing what a vendor supposedly requires.'],['Keep visible content and structured data aligned','Structured data is strongest when it describes content that is actually visible and maintained on the page. Divergence between markup and visible content creates trust and maintenance risk even when the JSON parses.'],['Do not sell schema as an AI citation guarantee','Structured data can improve machine readability and semantic clarity, but an evidence-first product should not claim that a particular schema block guarantees ChatGPT, Gemini, Perplexity or search placement.'],['Revalidate after template changes','Theme, CMS and component changes can duplicate or break JSON-LD. Structured data should therefore be included in regression scans rather than treated as a one-time setup task.']],sources:['https://htmlandhtml.com/sources.json']},
 {slug:'/en/guides/ai-search-visibility',tr:'/tr/rehberler/ai-arama-gorunurlugu',title:'AI Search Visibility: From Crawl Eligibility to Measured Mentions',desc:'A practical model for separating technical eligibility, retrieval evidence and neutral-prompt mention measurement.',tool:'/en/ai-mention-tracker',sections:[['Eligibility comes before mention tracking','A site that blocks relevant retrieval crawlers or exposes unstable public content may reduce its opportunity to be discovered. Technical access is therefore a prerequisite layer, not a mention metric.'],['Mentions and citations are different','A generated answer can mention a brand without citing its domain, and it can cite a domain without using the exact brand string. A serious tracker should measure those states separately.'],['Neutral prompts reduce self-injection','If the tracked brand or domain is included in the test prompt, the measurement is biased. Neutral prompts make the observation more useful by asking the provider to retrieve or generate without being handed the target entity.'],['API surfaces are not consumer-app replicas','Provider APIs and consumer products can use different models, retrieval policies or ranking layers. Results should therefore identify the measured surface and avoid claiming they exactly reproduce the consumer application.'],['Time series creates the real decision value','One observation is a snapshot. Repeating the same neutral prompt set under a stable measurement contract creates a trend that can be compared with technical changes, content releases or crawl-policy updates.']],sources:['https://platform.openai.com/docs/quickstart/make-your-first-api-request','https://docs.perplexity.ai/api-reference/sonar-post','https://ai.google.dev/gemini-api/docs/google-search']}
 ],
 tr:[]
};

guideData.tr=[
 {slug:'/tr/rehberler/ai-web-sitesi-hazirlik-kontrol-listesi',en:'/en/guides/ai-website-readiness-checklist',title:'AI Web Sitesi Hazırlık Kontrol Listesi: Kanıt Öncelikli Teknik Çerçeve',desc:'Crawl erişimi, teknik SEO, AI crawler politikası, llms.txt, yapısal veri, erişilebilirlik, güvenlik, güven ve linkleri tek bir sinyali ranking garantisi gibi sunmadan değerlendiren pratik kontrol listesi.',tool:'/tr/site-tarama',sections:[['AI etiketlerinden önce crawl erişimini çözün','Bir sayfa güvenilir biçimde fetch edilemiyor, keşfedilemiyor veya indekslenemiyorsa AI’ya özgü dosya eklemek temel erişim sorununu çözmez. Önce HTTP durumu, redirect, robots davranışı, sitemap görünürlüğü ve sayfa keşfini doğrulayın.'],['Teknik kanıtı ürün heuristiğinden ayırın','Faydalı bir readiness audit doğrudan HTTP/HTML kanıtını vendor dokümanından, gelişmekte olan önerilerden ve iç heuristiklerden ayırır. Böylece skor, alttaki kuralın otoritesinden daha fazlasını ima etmez.'],['Makine-okunabilir yüzeyleri katman olarak ele alın','llms.txt, Markdown alternate, structured data ve OpenAPI makine okunabilirliğine veya keşif bağlamına katkı sağlayabilir; fakat crawl erişimi, içerik kalitesi ve güvenilir site kimliğinin yerini tutmaz.'],['Field performans verisi uydurmayın','Statik HTML response size veya script yoğunluğu gibi performans hijyeni sinyalleri gösterebilir. Güvenilir LCP, INP ve CLS için field/lab verisi gerekir; veri yoksa NOT_MEASURED dönmelidir.'],['Re-scan ile döngüyü kapatın','Hazırlık çalışması uygulama sonrası aynı karar sözleşmesi yeniden çalıştırıldığında tamamlanır. Before/after kanıtı, hangi ölçülebilir koşulların gerçekten değiştiğini gösterir.']],sources:['https://www.rfc-editor.org/rfc/rfc9309.html','https://help.openai.com/en/articles/12627856-publishers-and-developers-faq','https://llmstxt.org/','https://www.w3.org/TR/WCAG22/']},
 {slug:'/tr/rehberler/llms-txt',en:'/en/guides/llms-txt',title:'llms.txt Nedir, Ne Değildir ve Nasıl Doğrulanır?',desc:'llms.txt v2, discovery ilişkileri, link erişilebilirliği ve proposal sınırlarını kaynaklı biçimde açıklayan rehber.',tool:'/tr/llms-txt-validator',sections:[['llms.txt zorunlu ranking standardı değildir','Dosya, sitenin LLM odaklı kısa bir haritasını sunmak için gelişmekte olan yararlı bir convention’dır. IETF, W3C veya arama sıralaması gerekliliği gibi anlatılmamalıdır.'],['Yapı yalnız ilk kontroldür','Metin dosyası sözdizimsel olarak temiz olup kırık veya redirect yapan kaynaklara işaret edebilir. Bu nedenle validation, Markdown yapısını gerçek HTTP erişilebilirliğinden ayırmalıdır.'],['Discovery ayrıca ölçülmelidir','Güncel proposal rel="describedby" ve Markdown alternate gibi discovery mekanizmalarını içerir. Bunlar faydalı sinyallerdir fakat normatif web protokol kuralı gibi puanlanmamalıdır.'],['Linklenen kaynakları seçici tutun','llms.txt, uzun bir thin URL listesi yerine stabil, canonical ve yüksek bilgi yoğunluklu sayfalara işaret ettiğinde daha faydalıdır. Güçlü information architecture dosyanın bakımını kolaylaştırır.'],['Deploy sonrası tekrar doğrulayın','Routing, redirect veya content-type değişiklikleri linklenen kaynakları sessizce bozabilir. Dosyayı sitenin bakımı yapılan makine-okunabilir yüzeylerinden biri olarak ele alın.']],sources:['https://llmstxt.org/','https://llmstxt.org/changes.html']},
 {slug:'/tr/rehberler/ai-tarayici-erisimi',en:'/en/guides/ai-crawler-access',title:'AI Tarayıcı Erişimi: robots.txt, Arama Retrieval ve Vendor Kontrolleri',desc:'Arama crawler’ları, kullanıcı yönlendirmeli retrieval ve model-geliştirme veri toplama kontrollerini birbirinden ayıran vendor kaynaklı rehber.',tool:'/tr/ai-crawler-checker',sections:[['Robots protokolü ile vendor anlamını ayırın','RFC 9309 Robots Exclusion Protocol davranışını tanımlar. Vendor dokümanı ise her crawler tokenının hangi ürün amacıyla kullanıldığını açıklar. Doğru audit iki katmanı birlikte ele alır.'],['OpenAI search erişimi placement garantisi değildir','OpenAI OAI-SearchBot’u search eligibility bağlamında dokümante eder. Erişime izin vermek dahil olabilmenin ön koşullarından biri olabilir; placement, ranking veya citation garantisi değildir. GPTBot ile search erişimi aynı kontrol gibi ele alınmamalıdır.'],['Anthropic farklı crawler rollerini ayırır','Anthropic model geliştirme, kullanıcı yönlendirmeli retrieval ve search için farklı crawler kimlikleri dokümante eder. Hepsini tek “Claude bot” olarak ele almak politika hassasiyetini kaybettirir.'],['Perplexity ve Google ayrı okunmalıdır','Perplexity, PerplexityBot için robots davranışını açıklar. Google ortak crawler’ları ve Google-Extended kontrolünü ayrı dokümante eder. Tek bir “AI’ya izin ver” anahtarı bu nedenle yeterli governance değildir.'],['Canlı robots yanıtını test edin','CMS editöründeki dosyayı audit etmek yeterli değildir. Deploy edilmiş robots.txt fetch edilmeli, redirect takip edilmeli ve effective user-agent grupları gerçekten doğrulanmalıdır.']],sources:['https://www.rfc-editor.org/rfc/rfc9309.html','https://help.openai.com/en/articles/12627856-publishers-and-developers-faq','https://support.anthropic.com/en/articles/8896518-does-anthropic-crawl-data-from-the-web-and-how-can-site-owners-block-the-crawler','https://www.perplexity.ai/help-center/en/articles/10354969-how-does-perplexity-follow-robots-txt','https://developers.google.com/crawling/docs/crawlers-fetchers/google-common-crawlers']},
 {slug:'/tr/rehberler/ai-icin-yapisal-veri',en:'/en/guides/structured-data-for-ai',title:'AI Hazırlığı İçin Yapısal Veri: Güvenilir Biçimde Ne Ölçülebilir?',desc:'Structured data’yı AI citation vaadine dönüştürmeden ölçülebilir semantik katman olarak kullanma rehberi.',tool:'/tr/schema-validator',sections:[['Parse edilebilirlikle başlayın','Bozuk JSON-LD semantik varlık değildir. Entity stratejisini tartışmadan önce blokların doğru parse edildiğini doğrulayın. Public HTML üzerinden syntax ve parse arızaları güvenilir biçimde raporlanabilir.'],['Entity type envanteri çıkarın','Bir site farklı template’lerde birden fazla entity type yayınlayabilir. Envanter, kimlik tutarsızlığı, eksik bağlam ve template drift’i görünür hale getirir.'],['Görünür içerikle structured data’yı hizalayın','Yapısal veri, sayfada gerçekten görünen ve bakımı yapılan içeriği anlattığında daha güvenlidir. Markup ile görünür içerik arasındaki ayrışma bakım ve güven riski yaratır.'],['Schema’yı AI citation garantisi gibi satmayın','Structured data makine okunabilirliğini ve semantik açıklığı artırabilir; belirli bir schema bloğunun ChatGPT, Gemini, Perplexity veya search placement garantisi olduğu iddia edilmemelidir.'],['Template değişikliğinden sonra tekrar doğrulayın','Tema, CMS ve component değişiklikleri JSON-LD’yi duplicate veya broken hale getirebilir. Structured data tek seferlik setup değil regression scan kapsamıdır.']],sources:['https://htmlandhtml.com/sources.json']},
 {slug:'/tr/rehberler/ai-arama-gorunurlugu',en:'/en/guides/ai-search-visibility',title:'AI Arama Görünürlüğü: Crawl Uygunluğundan Ölçülmüş Mention’a',desc:'Teknik uygunluk, retrieval kanıtı ve tarafsız-prompt mention ölçümünü birbirinden ayıran pratik model.',tool:'/tr/ai-mention-tracker',sections:[['Mention takibinden önce eligibility gelir','İlgili retrieval crawler’larını engelleyen veya stabil public içerik sunmayan bir site keşfedilme fırsatını azaltabilir. Teknik erişim mention metriği değil ön koşul katmanıdır.'],['Mention ile citation aynı şey değildir','Bir üretilmiş yanıt markayı anıp domaini cite etmeyebilir; domaini cite edip tam marka stringini kullanmayabilir. Ciddi tracker bu durumları ayrı ölçmelidir.'],['Tarafsız prompt self-injection riskini azaltır','Takip edilen marka veya domain test prompt’una yazılırsa ölçüm bias olur. Neutral prompt, provider’a hedef entity verilmeden retrieval/generation davranışını gözlemlemeyi sağlar.'],['API yüzeyi consumer uygulamanın birebir kopyası değildir','Provider API’leri ile consumer ürünler farklı model, retrieval veya ranking katmanları kullanabilir. Sonuç hangi yüzeyin ölçüldüğünü belirtmeli ve tüketici uygulamasını birebir temsil ettiğini iddia etmemelidir.'],['Asıl karar değeri zaman serisidir','Tek gözlem snapshot’tır. Aynı neutral prompt setini stabil measurement contract ile tekrar etmek, teknik değişiklikler ve içerik yayınlarıyla kıyaslanabilir trend üretir.']],sources:['https://platform.openai.com/docs/quickstart/make-your-first-api-request','https://docs.perplexity.ai/api-reference/sonar-post','https://ai.google.dev/gemini-api/docs/google-search']}
];

function guidePage(lang,g){const route=g.slug;const sections=g.sections.map(([h,p],i)=>`<section><span class="article-index">0${i+1}</span><h2>${esc(h)}</h2><p>${esc(p)}</p></section>`).join('');const sources=g.sources.map(u=>`<li><a href="${u}" rel="external noopener">${esc(u)}</a></li>`).join('');const c=L[lang];return shell({lang,route,title:`${g.title} | HTML&HTML`,desc:g.desc,kicker:lang==='tr'?'REHBER / KAYNAKLI KARAR DESTEĞİ':'GUIDE / SOURCED DECISION SUPPORT',h1:g.title,intro:g.desc,type:'TechArticle',schemaExtra:{headline:g.title,dateModified:updated,author:{'@type':'Organization',name:'HTML&HTML'}},body:`<article class="article-shell"><div class="article-body">${sections}<section><span class="article-index">${lang==='tr'?'KAYNAKLAR':'SOURCES'}</span><h2>${lang==='tr'?'Kaynak notları':'Source notes'}</h2><p>${lang==='tr'?'Bu sayfadaki vendor veya protokol davranışı iddiaları aşağıdaki birinci taraf / normatif kaynaklarla sınırlandırılmıştır. HTML&HTML product heuristics ayrıca etiketlenir.':'Vendor or protocol behavior claims on this page are bounded by the first-party or normative sources below. HTML&HTML product heuristics are labeled separately.'}</p><ul class="source-list">${sources}</ul></section></div><aside class="article-aside"><b>${lang==='tr'?'İLGİLİ ARAÇ':'RELATED TOOL'}</b><h3>${lang==='tr'?'Teoriyi gerçek domain üzerinde ölçün.':'Measure the theory on a real domain.'}</h3><a class="solid-cta" href="${g.tool}">${lang==='tr'?'Aracı aç':'Open tool'}</a><a href="${c.guides}">${lang==='tr'?'Tüm rehberler':'All guides'} →</a></aside></article>`})}

function guidesHub(lang){const c=L[lang];const cards=guideData[lang].map(g=>`<article class="ia-card"><span>${lang==='tr'?'REHBER':'GUIDE'}</span><h3>${esc(g.title)}</h3><p>${esc(g.desc)}</p><a href="${g.slug}">${lang==='tr'?'Rehberi oku':'Read guide'} →</a></article>`).join('');return shell({lang,route:c.guides,title:lang==='tr'?'AI Web Sitesi Hazırlık Rehberleri — HTML&HTML':'AI Website Readiness Guides — HTML&HTML',desc:lang==='tr'?'AI crawler, llms.txt, structured data, teknik readiness ve AI search visibility için kaynaklı, kanıt öncelikli rehberler.':'Sourced, evidence-first guides for AI crawlers, llms.txt, structured data, technical readiness and AI search visibility.',kicker:lang==='tr'?'BİLGİ MERKEZİ / KAYNAKLI':'KNOWLEDGE HUB / SOURCED',h1:lang==='tr'?'Arama niyetini <em>araçtan rehbere bağlayan</em> bilgi katmanı.':'A knowledge layer that connects <em>search intent to measurable tools.</em>',intro:lang==='tr'?'Her rehber, tek bir karar alanını açıklar ve doğrudan ölçüm yapan ilgili araca geri bağlanır. Thin içerik üretmek yerine az sayıda yüksek bilgi yoğunluklu sayfa tutulur.':'Each guide explains one decision area and links back to the tool that measures it. The strategy favors fewer high-information pages over thin content.',body:`<section class="section compact-section"><div class="ia-grid">${cards}</div></section>`})}

function methodologyPage(lang){const c=L[lang];return shell({lang,route:c.method,title:lang==='tr'?'HTML&HTML Metodolojisi — Kanıt, Güven, Skor ve Sınırlar':'HTML&HTML Methodology — Evidence, Confidence, Scoring & Boundaries',desc:lang==='tr'?'HTML&HTML 12-motor audit metodolojisi: kaynak sınıfları, confidence, unknown state, ağırlıklar, SSRF sınırları, field-data politikası ve ticari ayrım.':'Public methodology for the HTML&HTML 12-engine audit: source classes, confidence, unknown states, weights, SSRF boundaries, field-data policy and commercial separation.',kicker:lang==='tr'?'KAMUYA AÇIK METODOLOJİ':'PUBLIC METHODOLOGY',h1:lang==='tr'?'Her skorun <em>izlenebilir bir nedeni</em> olmalı.':'Every score needs a <em>traceable reason.</em>',intro:lang==='tr'?'Standart, vendor dokümanı, proposal, doğrudan ölçüm ve iç heuristik birbirine eşitmiş gibi sunulmaz. Ölçülemeyen sinyal pass veya fail olmaya zorlanmaz.':'Standards, vendor guidance, proposals, direct measurement and internal heuristics are not presented as equivalent. Unavailable evidence is not forced into pass or fail.',body:`<section class="section"><div class="method-list"><div class="method-item"><b>OFFICIAL_STANDARD</b><div><h3>${lang==='tr'?'Normatif standart':'Normative standard'}</h3><p>${lang==='tr'?'Formal protokol veya platform standardı.':'Formal protocol or platform standard.'}</p></div></div><div class="method-item"><b>OFFICIAL_VENDOR</b><div><h3>${lang==='tr'?'Birinci taraf vendor dokümanı':'First-party vendor guidance'}</h3><p>${lang==='tr'?'İlgili ürün veya crawler operatörünün güncel dokümanı.':'Current documentation from the relevant product or crawler operator.'}</p></div></div><div class="method-item"><b>PROPOSAL</b><div><h3>${lang==='tr'?'Gelişmekte olan öneri':'Emerging proposal'}</h3><p>${lang==='tr'?'llms.txt gibi faydalı ancak zorunlu web standardı olmayan convention.':'A useful convention such as llms.txt that is not a mandatory web standard.'}</p></div></div><div class="method-item"><b>MEASURED</b><div><h3>${lang==='tr'?'Doğrudan ölçüm':'Direct measurement'}</h3><p>HTTP / HTML / header / robots / link evidence.</p></div></div><div class="method-item"><b>INTERNAL_HEURISTIC</b><div><h3>${lang==='tr'?'Ürün heuristiği':'Product heuristic'}</h3><p>${lang==='tr'?'Normatif güç iddiası olmadan decision-support kuralı.':'Decision-support rule without normative-force claims.'}</p></div></div><div class="method-item"><b>EXPERIMENTAL</b><div><h3>${lang==='tr'?'Deneysel yüzey':'Experimental surface'}</h3><p>${lang==='tr'?'Düşük adoption / erken agent sinyali.':'Low-adoption or early agent signal.'}</p></div></div></div></section><section class="section"><header><span class="eyebrow">SCORING</span><h2>${lang==='tr'?'UNKNOWN başarısızlık değildir. Başarı da değildir.':'UNKNOWN is not failure. It is not success either.'}</h2><p>${lang==='tr'?'Reliable evidence yoksa kural denominator’dan çıkarılır. Core Web Vitals için field/lab veri yoksa NOT_MEASURED kalır.':'If reliable evidence is unavailable, the rule is excluded from the denominator. Core Web Vitals remain NOT_MEASURED without field/lab data.'}</p></header></section><section class="section"><header><span class="eyebrow">SAFETY</span><h2>SSRF fail-closed</h2><p>${lang==='tr'?'Private/local/reserved hedefler, credential içeren URL’ler, non-standard portlar ve private ağa redirect pivotları reddedilir.':'Private/local/reserved targets, credential-bearing URLs, non-standard ports and redirect pivots into private address space are rejected.'}</p></header><a class="text-cta" href="${c.standard}">${lang==='tr'?'Açık audit profile’a geç':'Open the audit profile'} →</a></section>`})}

function standardPage(lang){const c=L[lang];return shell({lang,route:c.standard,title:lang==='tr'?'HTML&HTML Açık Kanıt Standardı ve Audit Profile':'HTML&HTML Open Evidence Standard & Audit Profile',desc:lang==='tr'?'12 motorun ağırlıklarını, invariants kurallarını, kaynak sınıflarını, scan limitlerini ve ticari sınırı açıklayan kamuya açık HTML&HTML ürün profili.':'Public HTML&HTML product profile defining 12-engine weights, invariants, source classes, scan limits and commercial boundaries.',kicker:lang==='tr'?'AÇIK ÜRÜN PROFİLİ / V1.1':'OPEN PRODUCT PROFILE / V1.1',h1:lang==='tr'?'“Standart” kelimesi <em>harici otorite iddiası değildir.</em>':'“Standard” does <em>not imply third-party authority.</em>',intro:lang==='tr'?'Bu sayfa HTML&HTML’nin kendi public product profile’ını yayınlar. IETF, W3C, OpenAI, Anthropic, Google veya başka bir vendor standardı olduğu iddia edilmez.':'This page publishes HTML&HTML’s own public product profile. It is not presented as an IETF, W3C, OpenAI, Anthropic, Google or other vendor standard.',body:`<section class="section"><div class="authority-grid"><article class="authority-card"><b>12 ENGINES</b><h3>${lang==='tr'?'Ağırlık toplamı 100':'Weights total 100'}</h3><p>${lang==='tr'?'Public JSON profile, canonical engine ağırlıklarıyla drift testine tabidir.':'The public JSON profile is regression-tested against canonical engine weights.'}</p></article><article class="authority-card"><b>BOUNDARY</b><h3>${lang==='tr'?'50 public HTML sayfası':'50 public HTML pages'}</h3><p>${lang==='tr'?'Crawl, response, redirect, timeout ve link probe limitleri kontrollüdür.':'Crawl, response, redirect, timeout and link-probe limits are bounded.'}</p></article><article class="authority-card"><b>EVIDENCE</b><h3>${lang==='tr'?'Kaynak sınıfı zorunlu':'Source class required'}</h3><p>${lang==='tr'?'Measured, official, proposal ve heuristic aynı otorite gibi sunulmaz.':'Measured, official, proposal and heuristic evidence are not presented as equivalent authority.'}</p></article></div></section><section class="section"><div class="dual-cta"><a class="solid-cta" href="/audit-profile.json">audit-profile.json</a><a href="/sources.json">sources.json →</a><a href="${c.method}">${lang==='tr'?'Metodoloji':'Methodology'} →</a></div></section>`})}

function crawlerReference(lang){const c=L[lang];return shell({lang,route:c.crawlerRef,title:lang==='tr'?'AI Tarayıcı Referansı 2026 — OpenAI, Anthropic, Perplexity, Google':'AI Crawler Reference 2026 — OpenAI, Anthropic, Perplexity, Google',desc:lang==='tr'?'Search, user-directed retrieval, model-development collection ve product-control crawler rollerini birinci taraf kaynaklarla ayıran AI crawler referansı.':'Sourced reference separating search, user-directed retrieval, model-development collection and product-control crawler roles.',kicker:lang==='tr'?'REFERANS / VENDOR KAYNAKLI':'REFERENCE / VENDOR-SOURCED',h1:lang==='tr'?'“AI bot” tek bir <em>politika kategorisi değildir.</em>':'“AI bot” is not a single <em>policy category.</em>',intro:lang==='tr'?'Crawler adının varlığından amaç çıkarılmaz. Search, training/model-development, user-directed retrieval ve product controls vendor dokümanına göre ayrı okunur.':'Crawler purpose is not inferred from the name alone. Search, training/model-development, user-directed retrieval and product controls are separated using vendor documentation.',body:`<section class="section"><div class="method-list"><div class="method-item"><b>OPENAI</b><div><h3>OAI-SearchBot / GPTBot</h3><p>${lang==='tr'?'Search eligibility ile model-development collection aynı kontrol değildir. Placement veya citation garantisi çıkarılmaz.':'Search eligibility and model-development collection are not the same control. No placement or citation guarantee is inferred.'}</p><a href="https://help.openai.com/en/articles/12627856-publishers-and-developers-faq" rel="external">OpenAI source</a></div></div><div class="method-item"><b>ANTHROPIC</b><div><h3>ClaudeBot / Claude-User / Claude-SearchBot</h3><p>${lang==='tr'?'Vendor tarafından farklı roller için ayrı crawler kimlikleri dokümante edilir.':'The vendor documents separate crawler identities for different roles.'}</p><a href="https://support.anthropic.com/en/articles/8896518-does-anthropic-crawl-data-from-the-web-and-how-can-site-owners-block-the-crawler" rel="external">Anthropic source</a></div></div><div class="method-item"><b>PERPLEXITY</b><div><h3>PerplexityBot</h3><p>${lang==='tr'?'robots.txt davranışı vendor dokümanına göre değerlendirilir.':'robots.txt behavior is evaluated against vendor documentation.'}</p><a href="https://www.perplexity.ai/help-center/en/articles/10354969-how-does-perplexity-follow-robots-txt" rel="external">Perplexity source</a></div></div><div class="method-item"><b>GOOGLE</b><div><h3>Googlebot / Google-Extended</h3><p>${lang==='tr'?'Search crawling ile Google-Extended product control aynı kavram değildir.':'Search crawling and the Google-Extended product control are separate concepts.'}</p><a href="https://developers.google.com/crawling/docs/crawlers-fetchers/google-common-crawlers" rel="external">Google source</a></div></div></div></section><section class="section"><div class="authority-callout"><div><h3>${lang==='tr'?'Kendi robots politikanızı canlı test edin.':'Test your live robots policy.'}</h3><p>${lang==='tr'?'Referans kavramları açıklar; checker gerçek site yanıtını ölçer.':'The reference explains the concepts; the checker measures the live site response.'}</p></div><a href="${lang==='tr'?'/tr/ai-crawler-checker':'/en/ai-crawler-checker'}">${lang==='tr'?'AI tarayıcı kontrolünü aç':'Open AI crawler checker'}</a></div></section>`})}

function trustPage(lang,type){const c=L[lang];const data={en:{about:['About HTML&HTML','HTML&HTML is an evidence-first website AI-readiness platform built around a public 12-engine scan core and a separate implementation product.','The product does not sell hidden findings. It publishes measurable problems and their evidence, then charges for implementation precision when a user wants a fix contract.','The public audit profile, source registry, methodology and repository are part of the trust model.'],contact:['Contact HTML&HTML','For product support, reproducible scanner defects or source-registry corrections, use the official public repository issue tracker. Do not post credentials, service-account JSON, API keys or private customer data in a public issue.','Repository: https://github.com/sagiarvil/html','Security-sensitive or private operational data should never be copied into public support channels.'],privacy:['Privacy','The public scanner is designed to inspect public HTTP/HTTPS surfaces. It does not require account registration for a scan and it does not intentionally request private network targets.','The service may receive the domain/URL submitted for scanning and public responses required to compute the result. Access-gated features can use server-side provider credentials; those credentials are not exposed in public page source.','Do not submit secrets, intranet targets or credential-bearing URLs.'],terms:['Terms of Use','HTML&HTML scores are diagnostic outputs, not guarantees of rankings, traffic, revenue, AI citations, legal compliance or security certification.','Use the scanner only against public targets you are authorized to test. Private/local/reserved targets and risky redirect pivots are intentionally rejected.','The paid Fix Mandate is an implementation decision-support contract and does not replace professional legal, security or accessibility certification.']},tr:{about:['HTML&HTML Hakkında','HTML&HTML, kamuya açık 12-motor tarama çekirdeği ve ayrı uygulama ürünü üzerine kurulu kanıt öncelikli AI web sitesi hazırlık platformudur.','Ürün gizli bulgu satmaz. Ölçülebilir sorunları ve kanıtlarını yayınlar; kullanıcı uygulama kontratı istediğinde uygulama kesinliğini ücretlendirir.','Public audit profile, source registry, metodoloji ve kaynak repo güven modelinin parçasıdır.'],contact:['HTML&HTML İletişim','Ürün desteği, tekrar üretilebilir scanner hataları veya source-registry düzeltmeleri için resmi public repository issue tracker kullanılmalıdır. Public issue içine credential, service-account JSON, API key veya özel müşteri verisi yazmayın.','Repository: https://github.com/sagiarvil/html','Güvenlik hassas veya özel operasyon verileri public destek kanalına kopyalanmamalıdır.'],privacy:['Gizlilik','Public scanner herkese açık HTTP/HTTPS yüzeylerini incelemek için tasarlanmıştır. Tarama için hesap kaydı gerekmez ve private network hedefleri bilinçli olarak istenmez.','Servis tarama için gönderilen domain/URL bilgisini ve sonucu hesaplamak için gereken public response’ları alabilir. Erişim kontrollü özellikler server-side provider credentials kullanabilir; bu secrets public sayfa kaynağına çıkarılmaz.','Secret, intranet hedefi veya credential içeren URL göndermeyin.'],terms:['Kullanım Koşulları','HTML&HTML skorları teşhis çıktısıdır; ranking, trafik, gelir, AI citation, hukuki uyum veya güvenlik sertifikası garantisi değildir.','Scanner’ı yalnız test etmeye yetkili olduğunuz public hedeflerde kullanın. Private/local/reserved hedefler ve riskli redirect pivotları bilinçli olarak reddedilir.','Ücretli Fix Mandate uygulama karar destek kontratıdır; profesyonel hukuk, güvenlik veya erişilebilirlik sertifikasyonunun yerini tutmaz.']}}[lang][type];const route={about:c.about,contact:c.contact,privacy:c.privacy,terms:c.terms}[type];return shell({lang,route,title:`${data[0]} | HTML&HTML`,desc:data[1],kicker:lang==='tr'?'GÜVEN YÜZEYİ':'TRUST SURFACE',h1:data[0],intro:data[1],body:`<article class="article-shell"><div class="article-body"><section><h2>${lang==='tr'?'Politika':'Policy'}</h2><p>${esc(data[2])}</p></section><section><h2>${lang==='tr'?'Sınır':'Boundary'}</h2><p>${esc(data[3])}</p></section></div></article>`})}

