// Machine-readable navigation graph for LLM retrieval.
const llms=`# HTML&HTML\n\n> HTML&HTML is an evidence-first AI Website Readiness platform. One canonical 12-engine public scan core powers focused tools, sourced guidance, a $149 implementation-grade Fix Mandate and an access-gated AI Mention Tracker. Evidence is free; implementation precision is the paid product.\n\n## Language hubs\n- [English hub](${base}/en): Global default product and tool directory.\n- [Türkçe ana sayfa](${base}/tr): Tam Türkçe ürün, araç ve rehber yapısı.\n\n## Platform and commercial boundary\n- [Platform](${base}/en/platform)\n- [TR Platform](${base}/tr/platform)\n- [Pricing](${base}/en/pricing): Public diagnosis USD 0; Full Site Fix Mandate USD 149 per domain/engagement.\n- [TR Fiyatlandırma](${base}/tr/fiyatlandirma)\n- [Fix Mandate](${base}/en/fix-mandate)\n- [TR Fix Mandate](${base}/tr/fix-mandate)\n\n## Focused tools — English\n${tools.en.map(t=>`- [${t.name}](${base}${t.slug}): ${t.desc}`).join('\n')}\n\n## Odaklı araçlar — Türkçe\n${tools.tr.map(t=>`- [${t.name}](${base}${t.slug}): ${t.desc}`).join('\n')}\n\n## Guides — English\n${guideData.en.map(g=>`- [${g.title}](${base}${g.slug}): ${g.desc}`).join('\n')}\n\n## Rehberler — Türkçe\n${guideData.tr.map(g=>`- [${g.title}](${base}${g.slug}): ${g.desc}`).join('\n')}\n\n## Methodology and evidence governance\n- [English methodology](${base}/en/methodology)\n- [Türkçe metodoloji](${base}/tr/methodology)\n- [English evidence standard](${base}/en/evidence-standard)\n- [Türkçe kanıt standardı](${base}/tr/kanit-standardi)\n- [AI crawler reference](${base}/en/reference/ai-crawlers)\n- [AI tarayıcı referansı](${base}/tr/referans/ai-tarayicilar)\n- [Machine-readable audit profile](${base}/audit-profile.json)\n- [External evidence source registry](${base}/sources.json)\n- [OpenAPI 3.1 contract](${base}/openapi.json)\n\n## Trust and policy\n- [About](${base}/en/about) · [Hakkımızda](${base}/tr/hakkimizda)\n- [Contact](${base}/en/contact) · [İletişim](${base}/tr/iletisim)\n- [Privacy](${base}/en/privacy) · [Gizlilik](${base}/tr/gizlilik)\n- [Terms](${base}/en/terms) · [Kullanım Koşulları](${base}/tr/kullanim-kosullari)\n\n## Scan boundaries\n- Up to 50 public HTML pages and 30 link probes per scan.\n- Private/local/reserved targets, credential-bearing URLs, non-standard ports and redirect pivots into private address space fail closed.\n- Unknown or unavailable measurements are excluded from the relevant score denominator rather than forced to pass or fail.\n- Reliable LCP, INP and CLS remain NOT_MEASURED without appropriate field/lab integration.\n- Public scanning does not invent source-file paths. File-level targeting requires source/codebase context.\n- A score is not a guarantee of rankings, traffic, revenue or AI citations.\n- llms.txt is treated as a PROPOSAL, not a mandatory web standard.\n`;write('llms.txt',llms);
write('index.md',`# HTML&HTML — AI Website Readiness\n\nHTML&HTML is organized as a bilingual intent graph rather than one oversized landing page.\n\n## English\n- Home: ${base}/en\n- Platform: ${base}/en/platform\n- Tools: ${base}/en/tools\n- Guides: ${base}/en/guides\n- Pricing: ${base}/en/pricing\n- Methodology: ${base}/en/methodology\n\n## Türkçe\n- Ana sayfa: ${base}/tr\n- Platform: ${base}/tr/platform\n- Araçlar: ${base}/tr/araclar\n- Rehberler: ${base}/tr/rehberler\n- Fiyatlandırma: ${base}/tr/fiyatlandirma\n- Metodoloji: ${base}/tr/methodology\n\n## Decision contract\nThe same canonical 12-engine core powers every focused diagnostic surface. Specialized pages filter presentation scope; they do not create competing scoring engines. Evidence is public. The paid Fix Mandate sells implementation sequence, testing and rollback.\n`);

// Enterprise IA regression contract.
write('tests/integrity/ia.mjs',`import fs from 'node:fs';\nconst read=p=>fs.readFileSync(p,'utf8');const exists=p=>fs.existsSync(p);const errors=[];\nconst pairs=${JSON.stringify(routePairs)};\nfor(const [en,tr] of pairs){for(const [route,lang,alt] of [[en,'en',tr],[tr,'tr',en]]){const rel=route.slice(1)+'/index.html';if(!exists(rel)){errors.push('missing '+rel);continue}const s=read(rel);if(!s.includes('<html lang="'+lang+'"'))errors.push(rel+': lang');if(!s.includes('rel="canonical" href="https://htmlandhtml.com'+route+'"'))errors.push(rel+': canonical');if(!s.includes('hreflang="'+(lang==='en'?'tr':'en')+'" href="https://htmlandhtml.com'+alt+'"'))errors.push(rel+': hreflang');if(!s.includes('BreadcrumbList')&&!['/en','/tr'].includes(route))errors.push(rel+': breadcrumb schema');if(/\\?lang=(en|tr)/.test(s))errors.push(rel+': query-language link');}}\nconst firebase=JSON.parse(read('firebase.json'));if(!firebase.hosting.redirects.some(x=>x.source==='/'&&x.destination==='/en'&&x.type===301))errors.push('root must 301 to /en');\nconst sitemap=read('sitemap.xml'),llms=read('llms.txt');for(const [en,tr] of pairs)for(const r of [en,tr]){if(!sitemap.includes('https://htmlandhtml.com'+r))errors.push('sitemap missing '+r);if(!llms.includes('https://htmlandhtml.com'+r))errors.push('llms missing '+r)}\nfor(const hub of ['en/index.html','tr/index.html']){const s=read(hub);for(const token of ['/platform','/tools','/araclar','/guides','/rehberler']){/* structural coverage below */}if(!s.includes('toolScanForm'))errors.push(hub+': scanner missing');if(!s.includes('site-ia.css'))errors.push(hub+': IA css missing')}\nconst en=read('en/index.html'),tr=read('tr/index.html');for(const r of ['/en/platform','/en/tools','/en/guides','/en/pricing'])if(!en.includes('href="'+r+'"'))errors.push('EN hub missing '+r);for(const r of ['/tr/platform','/tr/araclar','/tr/rehberler','/tr/fiyatlandirma'])if(!tr.includes('href="'+r+'"'))errors.push('TR hub missing '+r);\nfor(const p of ['assets/css/site-ia.css','scripts/build-enterprise-ia.mjs'])if(!exists(p))errors.push('missing '+p);\nif(errors.length){console.error('ENTERPRISE IA FAIL');for(const e of errors)console.error('- '+e);process.exit(1)}console.log('ENTERPRISE IA PASS: locale hubs, intent pages, hreflang/canonical graph, sitemap, llms and root migration verified.');\n`);

// Package scripts.
const pkg=JSON.parse(read('package.json'));pkg.version='7.0.0';pkg.description='HTML&HTML enterprise bilingual AI Website Readiness platform with one canonical 12-engine scan core, intent-focused tools, sourced guides and implementation mandates';pkg.scripts['build:ia']='node scripts/build-enterprise-ia.mjs';pkg.scripts['test:ia']='node tests/integrity/ia.mjs';pkg.scripts['test:integrity']='node tests/integrity/check.mjs && node tests/integrity/authority.mjs && node tests/integrity/i18n.mjs && node tests/integrity/ia.mjs';write('package.json',JSON.stringify(pkg,null,2)+'\n');

console.log('Enterprise global IA generated:',routePairs.length*2,'localized canonical URLs');
